### Python Sidecar Engine

```python
from fastapi import FastAPI
import psutil
import threading
import time
import signal

app = FastAPI()

# Thread-safe queue for background worker
class Queue:
    def __init__(self):
        self.queue = []
        self.lock = threading.Lock()

    def enqueue(self, item):
        with self.lock:
            self.queue.append(item)

    def dequeue(self):
        with self.lock:
            if not self.queue:
                return None
            return self.queue.pop(0)

queue = Queue()

# Background worker thread function
def background_worker():
    while True:
        # Simulate work by dequeuing an item from the queue
        item = queue.dequeue()
        if item is None:
            time.sleep(1)
        else:
            print(f"Processing: {item}")

# Start background worker in a separate thread
worker_thread = threading.Thread(target=background_worker, daemon=True)
worker_thread.start()

@app.get("/api/health")
def health():
    ram_usage = psutil.virtual_memory().percent
    vram_usage = 0.0  # Placeholder for VRAM usage (not available via psutil)
    return {"ram_usage": ram_usage, "vram_usage": vram_usage}

# Graceful shutdown handler
def graceful_shutdown(signum, frame):
    print("Received shutdown signal")
    worker_thread.join()
    exit(0)

signal.signal(signal.SIGINT, graceful_shutdown)
signal.signal(signal.SIGTERM, graceful_shutdown)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
```

