use reqwest;
use std::time::{Duration, Instant};
use tauri::{AppHandle, Manager};

fn poll_health(app_handle: AppHandle) {
    let start = Instant::now();
    loop {
        if let Ok(response) = reqwest::get("http://127.0.0.1:8000/api/health").await {
            if response.status().is_success() {
                println!("Health check passed");
                return;
            }
        }
        if start.elapsed() > Duration::from_secs(3600) { // 1 hour timeout
            eprintln!("Failed to connect to health endpoint after 1 hour");
            break;
        }
        std::thread::sleep(Duration::from_secs(2)); // Exponential backoff
    }

    app_handle.exit(0);
}

#[tauri::command]
fn start_sidecar(app_handle: AppHandle) {
    let handle = std::process::Command::new("python")
        .arg("./sidecar.py")
        .spawn()
        .expect("Failed to start sidecar process");

    // Spawn a new thread to poll health endpoint
    std::thread::spawn(move || poll_health(app_handle));
}

fn main() {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![start_sidecar])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
